// === Tab: mySketch ===
// 第一部分 // by SamuelYAN (Modified for 3-Stage Interaction)
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

let mySize;
let theShader;

// 累计流动的距离
let scrollY = 0;

// 交互相关变量
let pressStartTime = 0;
let isPressing = false;

function preload() {
  // 这里的 vert 和 frag 对应后面两部分代码定义的变量名
  theShader = createShader(vert, frag);
}

function setup() {
  mySize = max(windowWidth, windowHeight) * 1.0;
  createCanvas(mySize / 16 * 11, mySize, WEBGL);
  noStroke();
}

function draw() {
  shader(theShader);

  // --- 1. 计算按压持续时间 (Duration) ---
  let duration = 0.0; 

  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
    if (!isPressing) {
      isPressing = true;
      pressStartTime = millis(); // 记录刚按下的时刻
    }
    // 计算持续秒数
    duration = (millis() - pressStartTime) / 1000.0;
  } else {
    // 松开鼠标，重置
    isPressing = false;
    duration = 0.0;
  }

  // --- 2. 速度控制 (已改名 moveSpeed 避免报错) ---
  // 按下时速度为 0.08，平时为 0.02
  let moveSpeed = ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) ? 0.08 : 0.02;

  // 累加位置 (+= 代表向上流动)
  scrollY += moveSpeed;

  // --- 3. 传递 Uniforms 给 Shader ---
  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0);
  theShader.setUniform("u_frame", frameCount / 1.0);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / 100.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0) / 100.0]);

  theShader.setUniform("u_scrollY", scrollY);       // 传递位移
  theShader.setUniform("u_pressDuration", duration); // 传递按压时间

  rect(0, 0, width, height);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

// === Tab: frag ===
// 第二部分 // by SamuelYAN (Modified by Gemini: 3-Stage Interaction)
// noprotect
const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform float u_scrollY;
uniform float u_pressDuration;

// --- hash + noise ---
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    vec2 u = f * f * (3.0/1. - 2.0 * f/1.);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float value = 0.0;
    float amplitude = 0.25;
    for (int i = 0; i < 2; i++) {
        value += amplitude * noise(p);
        p *= 1.25;
        amplitude *= 0.125;
    }
    return value;
}

float contourLines(float v, float frequency, float line_thickness) {
    float lines = abs(fract(v * frequency) - 0.299);
    return smoothstep(0.5 - line_thickness, 0.499 + line_thickness, lines);
}

void main() {
    vec2 uv = gl_FragCoord.xy / u_resolution.xy;

    // --- [1] 计算交互过渡因子 ---
    // t1: 0秒 -> 5秒 (变红阶段)
    float t1 = smoothstep(0.0, 5.0, u_pressDuration);
    // t2: 5秒 -> 6秒 (变白/变滑阶段)
    float t2 = smoothstep(5.0, 6.0, u_pressDuration);

    // --- [2] 纹理坐标处理 ---
    uv = uv * -7.0 - 10.0; 
    uv.x *= u_resolution.x / u_resolution.y;

    // 扭曲计算
    vec2 warp1 = vec2(
        noise(uv * 1.0 + vec2(u_time * 0.5, u_time * 0.5)),
        noise(uv * 120.0/1. + vec2(-u_time * 0.4, u_time * 0.2))
    );
    vec2 uv2 = uv + (warp1 - 0.25) * 0.6;

    vec2 warp2 = vec2(
        noise(uv2 * 1. + vec2(-u_time * 0.6, u_time * 0.4)),
        noise(uv2 * 190.0/1. + vec2(u_time * 2.5, u_time * 0.3))
    );
    vec2 uvFinal = uv2 + (warp2 - 1.5) / 0.995;

    // 向上流动的向量 (由 JS 控制速度)
    vec2 flow = uvFinal + vec2(0.0, u_scrollY); 

    float n = fbm(flow);

    float n1 = fbm(flow + vec2(0.001, 0.0));
    float n2 = fbm(flow + vec2(0.0, 0.001));
    float grad = length(vec2(n1 - n, n2 - n));
    float edge = smoothstep(0.02, 0.2, grad);

    float frequency = sin(u_time*0.1) * 10.0/2.+10./1.;

    // --- [3] 动态改变材质 ---
    // 当 t2 (超过5秒) 增加时，线条变粗，锋利度降低
    float thickness = mix(0.125, 0.3, t2); 
    float lines = contourLines(n, frequency, thickness);

    // 锋利度控制：0.01 是极其锋利(有噪点)，0.3 是柔和
    float sharpDenominator = mix(0.01, 0.3, t2);

    // 计算黑白结构 (保留你喜欢的褶皱感)
    float finalValBW = mix(lines/.99, 1.0/sharpDenominator, edge * 0.9);
    float structureMask = clamp(finalValBW, 0.0, 1.0);

    // --- [4] 动态颜色混合 ---

    // 阶段0: 正常态 (绿/金)
    vec3 bg0 = mix(vec3(0.1, 0.35, 0.2), vec3(0.4, 0.7, 0.3), n * 1.5);
    vec3 fg0 = vec3(1.0, 1.0, 0.7); 

    // 阶段1: 危险态 (暗红/红白)
    vec3 bg1 = vec3(0.4, 0.1, 0.1); 
    vec3 fg1 = vec3(0.95, 0.8, 0.8); 

    // 阶段2: 过载态 (白/极淡绿)
    vec3 bg2 = vec3(0.9, 0.95, 0.92); 
    vec3 fg2 = vec3(1.0, 1.0, 1.0); 

    // 混合计算:
    // 先算 0 -> 1 的变化
    vec3 currentBg = mix(bg0, bg1, t1);
    vec3 currentFg = mix(fg0, fg1, t1);

    // 再算 -> 2 的变化
    currentBg = mix(currentBg, bg2, t2);
    currentFg = mix(currentFg, fg2, t2);

    // 最终合成：随着变得光滑，调整光晕的对比度(maskPower)
    float maskPower = mix(0.8, 1.8, t2);
    vec3 finalColor = mix(currentBg, currentFg, pow(structureMask, maskPower));

    gl_FragColor = vec4(finalColor, 1.0);
}
`;

// === Tab: vert ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

